var CARDS=function(R){var t=R.tot;return '<div class="eccards">'+[['Built-up area',F0(t.bua),'m²'],['Energy use (EPI)',F1(t.epi),'kWh/m²/yr'],['Electricity',F0(t.el),'kWh/yr'],['Cooling load',F0(t.cool),'kWh (heat)/yr'],['Peak cooling load',F1(t.tr)+' TR',F0(t.pk)+' kW'],['Area per TR',F0(t.m2tr),'m² of air-conditioned area'],['Peak heating load',F1(t.phk),'kW'],['Outdoor air (ASHRAE 62.1)',F0(t.Q),'L/s'],['Heat gain, envelope',F0(t.gain),'kWh/yr'],['Heat loss',F0(t.loss),'kWh/yr'],['Thermal energy',F1(t.th),'GJ/yr'],['Water use',F0(t.wt),'kL/yr'],['Water use per m²',F2(t.wpi),'kL/m²/yr'],['Embodied carbon',F0(t.emb),'tCO₂e'],['Embodied carbon per m²',F0(t.embI),'kg CO₂e/m²'],['Renewable share',F1(t.ren),'% of electricity'],['Operational emissions',F1(t.co2),'tCO₂e/yr'],['Checks passed',R.pass+' of '+R.checks.length,'']].map(function(c){return '<div><span>'+E_(c[0])+'</span><b>'+E_(c[1])+'</b> <small>'+E_(c[2])+'</small></div>'}).join('')+'</div>'};
var HEAD=function(){var c=PGE[ID],u=PU[ID],t=u.tab;return '<div class="card"><h3>'+esc(c.n)+'</h3><div class="row" translate="no" style="flex-wrap:wrap">'+c.tabs.map(function(x){return '<button class="'+(t==x[0]?'on':'')+'" onclick="pttab(\''+ID+'\',\''+x[0]+'\')">'+esc(x[1])+'</button>'}).join('')+'</div>'+(u.msg?'<p class="warn">'+esc(u.msg)+'</p>':'')+'<p class="mut" style="font-size:12px">Data is stored in this browser. Export to Excel regularly and keep the exports safe.</p></div>'};
