var VIEW={
 model:function(){var R=CALC(PD(ID)),u=PU[ID],mt=u.mt||'gain',s=PD(ID).set;
  var hfb={},hlb={};Object.keys(R.hf).forEach(function(k){if(R.hf[k]>0)hfb[k]=Math.round(R.hf[k])});Object.keys(R.hl).forEach(function(k){if(R.hl[k]>0)hlb[k]=Math.round(R.hl[k])});
  return '<div class="card"><h4>Building model, floor by floor</h4><p class="mut" style="margin:0">Each floor is coloured by the value you choose: the darker the colour, the higher the value. Hover over a floor to see all its values. Values marked "est." are worked out from the building profile because no metered value was entered.</p>'
  +'<div class="ecseg" translate="no">'+Object.keys(MT).map(function(k){return '<button class="'+(mt==k?'on':'')+'" style="--mc:'+MT[k][2]+'" onclick="ecmt(\''+k+'\')">'+esc(MT[k][0])+'</button>'}).join('')+'<button class="'+(u.pm?'on':'')+'" onclick="ecpm()">Per m²</button></div>'
  +'<div class="ecm"><div>'+PIC(R,mt,u.pm)+'</div><div>'+CARDS(R)+'</div></div></div>'
  +'<div class="card">'+HRBAR('Heat entering in the cooling season (kWh/yr)',hfb)+HRBAR('Heat leaving in the cold season (kWh/yr)',hlb)+'</div>'
  +'<div class="card"><h4>Floor-wise results</h4><div class="tw"><table class="bt"><tr><th>Floor</th><th>Use</th><th>Area m²</th><th>Heat gain kWh</th><th>Heat loss kWh</th><th>Cooling load kWh</th><th>Peak cooling TR</th><th>Electricity kWh</th><th>kWh/m²</th><th>Thermal GJ</th><th>Water kL</th></tr>'+R.floors.slice().reverse().map(function(x){return '<tr><td class="l">'+E_(x.name)+'</td><td>'+E_(x.f.use)+'</td><td>'+F0(x.A)+'</td><td>'+F0(x.gain)+'</td><td>'+F0(x.loss)+'</td><td>'+F0(x.cool)+'</td><td>'+F1(x.pk/3.517)+'</td><td>'+F0(x.el)+(x.elIsEst?' <span class="mut">est.</span>':'')+'</td><td>'+(x.A?F1(x.el/x.A):'-')+'</td><td>'+F1(x.th)+'</td><td>'+F0(x.wt)+(x.wtEst?' <span class="mut">est.</span>':'')+'</td></tr>'}).join('')+'<tr><th>Building</th><th></th><th>'+F0(R.tot.bua)+'</th><th>'+F0(R.tot.gain)+'</th><th>'+F0(R.tot.loss)+'</th><th>'+F0(R.tot.cool)+'</th><th>'+F1(R.tot.tr)+'</th><th>'+F0(R.tot.el)+'</th><th>'+F1(R.tot.epi)+'</th><th>'+F1(R.tot.th)+'</th><th>'+F0(R.tot.wt)+'</th></tr></table></div>'+(R.tot.ctw?'<p class="mut">Water includes '+F0(R.tot.ctw)+' kL/yr of cooling tower make-up.</p>':'')+'</div>'
  +'<div class="card"><details><summary><b>How the numbers are worked out</b></summary><div class="mut" style="font-size:12.5px;line-height:1.6"><p><b>This is a simplified screening model.</b> It helps compare floors and options and shows where heat, energy and water go. Where ECSBC asks for a whole-building simulation (the performance route), MDSSPL runs a full hourly simulation separately.</p><p><b>Envelope:</b> wall and window areas come from the floor area (a square plan unless the perimeter is known), the floor height and the window-to-wall ratio. Basements have no exposed walls. The top floor carries the roof.</p><p><b>Weather (ASHRAE 2021 or ISHRAE):</b> the design values of the selected station are used. Cooling degree-hours above 23.3 °C (CDH) are scaled by the operating hours; heating degree-hours = heating degree-days (base 18.3 °C) × 24.</p><p><b>Heat gain</b> = U × area × CDH (walls, windows, roof) + window area × SHGC × sun on walls × 0.6 + roof sun absorbed (from the SRI). <b>Heat loss</b> = U × area × heating degree-hours + air leakage (0.5 air changes an hour) + outdoor air.</p><p><b>People</b> give sensible and latent heat by activity (ASHRAE table, e.g. office work 73 W + 59 W). <b>Outdoor air</b> (ASHRAE 62.1) = people × L/s per person + area × L/s per m². Its sensible load = 1.23 × L/s × CDH, and its moisture (latent) load = 3.01 × L/s × humidity-ratio difference (g/kg, from the design dry and wet bulb and the indoor set point) × equivalent full-load hours.</p><p><b>Cooling load</b> (air-conditioned floors) = envelope gain + people + lights and equipment + outdoor air. <b>Peak cooling load</b> = conduction at the design dry bulb + sun through windows (300 W/m² × SHGC) + roof sun + people + lights + equipment + outdoor air (sensible and latent); TR = kW ÷ 3.517. <b>Electricity</b> = metered value, or lights + plug loads + cooling (cooling load ÷ COP, or the cooling equipment entered) + fans and pumps + other equipment.</p><p><b>Water</b> = metered value, or occupants × litres per person per day (NBC Part 9) × days, less efficient-fixture savings, plus cooling tower make-up (about 2.1 litres per kWh of cooling). <b>Thermal energy</b> = entered fuel and heat. <b>Embodied carbon</b> = quantity × factor (replace with EPD values) + transport.</p></div></details></div>'},
 set:function(){var s=PD(ID).set;return '<div class="card ecpf"><h4>Building profile</h4><div class="fg">'+FLD('co',INP('co'))+FLD('bname',INP('bname'))+FLD('city',INP('city'))+FLD('btype',SEL('btype',['Office','Retail or mall','Hotel','Hospital','School or university','Assembly','Mixed use','Residential']))+FLD('code',SEL('code',['ECSBC 2024 (commercial)','ECBC 2017 (commercial, as notified by the state)','ENS 2024 (residential)']))+FLD('level',SEL('level',['ECSBC Compliant','ECSBC Plus','Super ECSBC','ENS compliant']))+FLD('zone',SEL('zone',Object.keys(CLIM)))+FLD('cl',INP('cl'))+FLD('cd',INP('cd'))+FLD('hrs',INP('hrs'))+FLD('days',INP('days'))+'</div>'
  +'<h4>Weather and design conditions (ASHRAE / ISHRAE)</h4><div class="ecnote">Pick the nearest ASHRAE 2021 weather station to fill the design values. To use the ISHRAE Indian Weather Data Handbook instead, choose it as the source and type the handbook values for your city over the ASHRAE ones. The heat gain, heat loss, peak cooling (TR) and outdoor-air loads all use these values.</div><div class="fg">'+FLD('station','<select onchange="ecst(this.value)">'+Object.keys(ASHC).concat(['Other (enter values)']).map(function(o){return '<option'+(String(s.station)==o?' selected':'')+'>'+esc(o)+'</option>'}).join('')+'</select>')+FLD('wsrc',SEL('wsrc',['ASHRAE 2021 climatic design data','ISHRAE Indian Weather Data Handbook','Other source (entered)']))+['d_hdb','d_cdb','d_cwb','d_hdd','d_cdd','d_cdh','d_rad','t_cool','rh_cool','t_heat'].map(function(k){return FLD(k,INP(k))}).join('')+'</div>'
  +'<h4>Building envelope (heat footprint)</h4><div class="fg">'+['wallU','roofU','winU','shgc','wwr','sri'].map(function(k){return FLD(k,INP(k))}).join('')+'</div>'
  +'<h4>Lighting, cooling and electricity</h4><div class="fg">'+['lpd','cop','fp','eft'].map(function(k){return FLD(k,INP(k))}).join('')+'</div>'
  +'<h4>Water</h4><div class="fg">'+['fixeff','wc','tap','shw'].map(function(k){return FLD(k,INP(k))}).join('')+FLD('rwh',SEL('rwh',YN))+FLD('stp',SEL('stp',YN))+'</div>'
  +'<h4>Use and services</h4><div class="fg">'+FLD('bms',SEL('bms',YN))+FLD('meter',SEL('meter',YN))+FLD('comm',SEL('comm',YN))+FLD('waste',SEL('waste',YN))+FLD('ieq',SEL('ieq',YN))+FLD('ev',INP('ev'))+'</div></div>'
  +'<div class="card ecpf"><h4>Reference limits used in the compliance check</h4><div class="ecnote">These are typical prescriptive values from ECBC 2017 and ENS for a quick check. Limits differ by climate zone, building type, target level and the code version your state has adopted. Confirm each value in the code before using the results for a submission.</div><div class="fg">'+['lim_wall','lim_roof','lim_win','lim_shgc','lim_wwr','lim_sri','lim_lpd','lim_cop','lim_retv','lim_ucold','epi_bm'].map(function(k){return FLD(k,INP(k))}).join('')+'</div></div>'},
 chk:function(){var R=CALC(PD(ID));return '<div class="card"><h4>Compliance check</h4><p class="mut">'+R.pass+' of '+R.checks.length+' checks passed, '+R.fail+' not met. "Note" items are for information or are optional.</p><div class="tw"><table class="bt"><tr><th>Area</th><th>Item</th><th>Required</th><th>Provided</th><th>Result</th><th>Reference</th></tr>'+R.checks.map(function(c){return '<tr><td>'+E_(c.area)+'</td><td class="l">'+E_(c.item)+'</td><td class="l">'+E_(c.req)+'</td><td>'+E_(c.got)+'</td><td class="'+(c.ok=='pass'?'ecok':c.ok=='fail'?'ecno':'ecinf')+'">'+(c.ok=='pass'?'✓ Pass':c.ok=='fail'?'✕ Not met':'Note')+'</td><td class="mut">'+E_(c.ref)+'</td></tr>'}).join('')+'</table></div><div class="ecnote">This check uses the reference limits in the Building profile and the simplified model. Where a state requires an empanelled third-party assessor to certify ECBC compliance, the final sign-off must come from one; MDSSPL prepares the documents and evidence up to that point.</div></div>'},
 ref:function(){var L=[['ECSBC 2024: Energy Conservation and Sustainable Building Code (commercial)','Bureau of Energy Efficiency','https://beeindia.gov.in/sites/default/files/BEE_ECSBC_2024.pdf','Applies to commercial buildings with a connected load of 100 kW or more, or a contract demand of 120 kVA or more, once a state adopts it. Levels: ECSBC Compliant, ECSBC Plus and Super ECSBC. Adds water, waste, materials, indoor environment and commissioning to the energy provisions.'],['ECSBC 2024: commercial building code (full text)','Bureau of Energy Efficiency','https://beeindia.gov.in/sites/default/files/ECSBC%202024_Building%20Code%20for%20Commercial%20Buildlings.pdf',''],['Eco Niwas Samhita (ENS) 2024: energy code for residential buildings','Bureau of Energy Efficiency','https://www.beeindia.gov.in/sites/default/files/BEE_ENS_2024.pdf','Limits heat gain through walls, roofs and windows (RETV) and promotes natural ventilation and daylight.'],['ECBC 2017 and state notifications (example: Haryana)','HAREDA','https://hareda.gov.in/ecbc-and-ens-buildings/','ECBC 2017 remains the code notified by most states; check which code your state enforces.'],['BEE star rating for buildings','Bureau of Energy Efficiency','https://beeindia.gov.in/en/buildings','Energy use per m² bands for offices, hospitals, shopping malls and other buildings.'],['Draft rule: mandatory star rating of large buildings (2026)','Business Standard','https://www.business-standard.com/industry/news/power-ministry-mandatory-star-rating-large-buildings-126071900311_1.html','Draft, July 2026: buildings of 20,000 m² or more; 3 to 5 stars mapped to ECSBC levels. Not yet final.'],['Draft rule: details of the rating framework','Powerline','https://powerline.net.in/2026/08/20/sustainable-development-mop-proposes-mandatory-energy-rating-framework-for-buildings/',''],['ECSBC 2024 overview and state adoption','IMPRI','https://www.impriindia.com/insights/policy-update/energy/',''],['National Building Code of India 2016 (Part 9 plumbing; Part 11 sustainability)','Bureau of Indian Standards','https://bis.gov.in/others/national-building-code/',''],['ASHRAE Handbook of Fundamentals 2021: climatic design data (Ch. 14)','ASHRAE','https://ashrae-meteo.info/','Design dry bulb, wet bulb, degree-days, degree-hours and solar radiation for 24 Indian weather stations, used for heat gain, heat loss and peak loads.'],['ISHRAE Indian Weather Data Handbook','ISHRAE','https://ishrae.in/','Indian city design conditions; select it as the source and enter its values to replace the ASHRAE ones.'],['ASHRAE Standard 62.1: ventilation and indoor air quality','ASHRAE','https://www.ashrae.org/technical-resources/bookstore/standards-62-1-62-2','Outdoor air per person and per m² for each space use; sensible and moisture load of the outdoor air.'],['ASHRAE Fundamentals: heat gain from occupants (sensible and latent)','Autodesk (ASHRAE table)','https://help.autodesk.com/cloudhelp/2014/ENU/Revit/files/GUID-7668C78B-7B33-4D60-B838-57D2656D8AD5.htm','Sensible and latent heat per person by activity.'],['ASHRAE Standard 55: thermal environmental conditions','ASHRAE','https://www.ashrae.org/technical-resources/bookstore/standard-55-thermal-environmental-conditions-for-human-occupancy','Indoor cooling and heating set points and humidity.'],['ASHRAE Standard 90.1 (basis of ECBC; Appendix G for the performance route)','ASHRAE','https://www.ashrae.org/technical-resources/bookstore/standard-90-1',''],['EN 15978 and ISO 21930: life-cycle stages and embodied carbon','Studio Matrx (explainer)','https://www.studiomatrx.org/students/embodied-carbon-and-life-cycle-design/life-cycle-stages-of-a-building','Stages A1–A3 (product), A4 (transport) and beyond.']];
  return '<div class="card"><h4>Standards and references</h4><p class="mut">The service follows these codes and references. Links open the official document or a reliable summary.</p><div class="tw"><table class="bt"><tr><th>Standard or reference</th><th>Published by</th><th>What it is used for</th></tr>'+L.map(function(x){return '<tr><td class="l"><a href="'+esc(x[2])+'" target="_blank" rel="noopener">'+esc(x[0])+' ↗</a></td><td>'+esc(x[1])+'</td><td class="l">'+esc(x[3])+'</td></tr>'}).join('')+'</table></div></div>'
  +'<div class="card"><h4>What this service covers, and what it does not</h4><p><b>Covered:</b> which code applies; building envelope and heat footprint (U-values, SHGC, window-to-wall ratio, cool roof, RETV); construction materials and embodied carbon (A1–A3 and transport); energy-consuming equipment; electricity, thermal energy and energy use per m²; renewable energy; water need, rainwater harvesting, reuse and efficient fixtures; use and services (occupancy, hours, controls, metering, commissioning, waste, indoor air); a floor-wise model and a compliance check; star-rating readiness; compliance forms.</p><p><b>Not covered:</b> structural, fire-safety and building-services design (we review the designs, not draw them); building permits and approvals; detailed airflow or daylight studies and on-site testing (through partners on request); GRIHA, IGBC or LEED submissions (we prepare the data); the final sign-off where a state requires an empanelled third-party assessor.</p><p><b>Linked services:</b> Energy Audits, Water Audits, GHG Accounting, Net Zero, LCA, Product Carbon Footprint, Zero Waste to Landfill and ESG/BRSR reporting.</p></div>'}};
